(function() {
    'use strict';

    class CalibraAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'La Calibración';
            this.version = '1.1.0';

            this.ROUNDS_EN = [
                {
                    title: 'Round 1 — Diagnosing the Current PM System',
                    body: 'SFC has just lost <strong>5 top performers</strong> (17% of all rating-5 employees). Patricia (Senior Engineer), David (Product Manager), Catalina (Head of Sales), Marco (Finance Manager), and Gabriela (Customer Success Lead) have all resigned.<br><br>Your first task: invest in diagnosing the root causes. A thorough diagnosis covering <em>all PM components</em> (objectives, evaluation, calibration, compensation, communication) will set the foundation for effective redesign. A narrow focus may miss critical issues.<br><br><strong>Current system problems:</strong> objectives lack clarity, evaluations are subjective, no calibration exists, compensation trails the market by 16%, and feedback is poor.'
                },
                {
                    title: 'Round 2 — Redesigning the Performance Management System',
                    body: 'Based on your diagnostic findings, it is time to design the new PM system. You must decide how much to invest in three key areas:<br><br><strong>1. Salary Adjustments:</strong> SFC pays Senior Engineers $5,500/mo vs. $6,500 market rate. Increasing base pay is expensive but essential for retention. Industry benchmarks suggest spending $400K–$600K/year for a 120-person company.<br><br><strong>2. Bonus Pool:</strong> A performance-linked variable bonus differentiates top performers from average ones. The old system gave an 8% raise at best. A well-funded bonus pool (around $200K/year) sends a strong signal.<br><br><strong>3. Calibration Investment:</strong> Without calibration, ratings are inconsistent across managers. Investing $40K+ in facilitation, training, and tools ensures a rating of 5 means the same in every department.'
                },
                {
                    title: 'Round 3 — Communication and Trust Repair',
                    body: 'The new system is designed. Now you must communicate it and attempt to recover departed talent.<br><br><strong>Talent Recovery:</strong> CEO Rafael can personally contact each departed top performer with counter-offers (salary match, title promotion, equity, retention bonuses). Realistically, SFC can recover 2–3 of the 5. Higher investment increases the odds, but diminishing returns apply above $300K.<br><br><strong>Manager Training:</strong> The best system fails if managers cannot execute it. Training in OKR facilitation, calibration sessions, and feedback delivery is critical. Skimping here (under $60K) risks returning to old habits. Investing $100K+ builds lasting capability.'
                },
                {
                    title: 'Round 4 — Implementation and Impact Measurement',
                    body: 'Final round: choose how to roll out the new system and measure its impact over 12 months.<br><br><strong>Implementation Pace:</strong><br>• <em>Aggressive (3 months):</em> Fast results but high risk of errors and change fatigue.<br>• <em>Moderate (6 months):</em> Balanced — pilot in Q2, full rollout by Q4. Recommended.<br>• <em>Gradual (12 months):</em> Low risk but delayed impact; top talent may leave before seeing change.<br><br><strong>Monitoring:</strong> Invest in surveys, analytics dashboards, and pulse checks. Without monitoring ($10–$30K), you are flying blind. Strong monitoring ($60K+) enables real-time course corrections and demonstrates commitment to employees.'
                }
            ];

            this.ROUNDS_ES = [
                {
                    title: 'Ronda 1 — Diagnóstico del Sistema de PM Actual',
                    body: 'SFC acaba de perder <strong>5 top performers</strong> (17% de todos los empleados con rating 5). Patricia (Senior Engineer), David (Product Manager), Catalina (Head de Ventas), Marco (Finance Manager) y Gabriela (Customer Success Lead) han renunciado.<br><br>Primera tarea: invertir en diagnosticar las causas raíz. Un diagnóstico profundo que cubra <em>todos los componentes del PM</em> (objetivos, evaluación, calibración, compensación, comunicación) establece la base para un rediseño efectivo. Un enfoque limitado puede pasar por alto problemas críticos.<br><br><strong>Problemas del sistema actual:</strong> los objetivos carecen de claridad, las evaluaciones son subjetivas, no existe calibración, la compensación está 16% por debajo del mercado, y el feedback es deficiente.'
                },
                {
                    title: 'Ronda 2 — Rediseño del Sistema de Performance Management',
                    body: 'Con base en el diagnóstico, es momento de diseñar el nuevo sistema. Debes decidir cuánto invertir en tres áreas clave:<br><br><strong>1. Ajuste Salarial:</strong> SFC paga $5,500/mes a Senior Engineers vs. $6,500 en el mercado. Aumentar la base es costoso pero esencial. El benchmark sugiere $400K–$600K/año para 120 empleados.<br><br><strong>2. Pool de Bonos:</strong> Un bono variable ligado a desempeño diferencia a los top performers. El sistema anterior daba máximo 8% de aumento. Un pool de ~$200K/año envía una señal fuerte.<br><br><strong>3. Inversión en Calibración:</strong> Sin calibración, los ratings son inconsistentes entre managers. Invertir $40K+ en facilitación, entrenamiento y herramientas asegura que un rating 5 signifique lo mismo en todos los departamentos.'
                },
                {
                    title: 'Ronda 3 — Comunicación y Reparación de Confianza',
                    body: 'El nuevo sistema está diseñado. Ahora debes comunicarlo e intentar recuperar el talento perdido.<br><br><strong>Recuperación de Talento:</strong> El CEO Rafael puede contactar personalmente a cada top performer con contraofertas (salario competitivo, título, equity, bonos de retención). Realísticamente, SFC puede recuperar 2–3 de los 5. Mayor inversión aumenta las probabilidades, pero los retornos disminuyen sobre $300K.<br><br><strong>Entrenamiento de Managers:</strong> El mejor sistema falla si los managers no pueden ejecutarlo. Entrenamiento en facilitación de OKRs, sesiones de calibración y feedback es crítico. Invertir menos de $60K arriesga volver a viejas prácticas. Invertir $100K+ construye capacidad duradera.'
                },
                {
                    title: 'Ronda 4 — Implementación y Medición de Impacto',
                    body: 'Ronda final: elegir cómo desplegar el nuevo sistema y medir su impacto en 12 meses.<br><br><strong>Ritmo de Implementación:</strong><br>• <em>Agresivo (3 meses):</em> Resultados rápidos pero alto riesgo de errores y fatiga de cambio.<br>• <em>Moderado (6 meses):</em> Equilibrado — piloto en Q2, rollout completo en Q4. Recomendado.<br>• <em>Gradual (12 meses):</em> Bajo riesgo pero impacto tardío; los top performers pueden irse antes de ver cambios.<br><br><strong>Monitoreo:</strong> Invertir en encuestas, dashboards, y pulse checks. Sin monitoreo ($10–$30K), se navega a ciegas. Monitoreo fuerte ($60K+) permite correcciones en tiempo real y demuestra compromiso con los empleados.'
                }
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    budget: 1500,
                    retentionRate: 85,
                    fairnessScore: 35,
                    satisfactionScore: 45,
                    talentRecovered: 0,
                    diagnosisQuality: 0,
                    systemDesignScore: 0,
                    communicationScore: 0,
                    budgetHistory: [],
                    retentionHistory: [],
                    fairnessHistory: [],
                    satisfactionHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    analysisInvest: 30,
                    focusArea: 3,
                    salaryBudget: 300,
                    bonusPool: 150,
                    calibrationInvest: 40,
                    recoveryBudget: 200,
                    trainingBudget: 60,
                    implSpeed: 2,
                    monitoringInvest: 40
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            var period = window.mySimulation.state.currentPeriod || 1;
            this._updateBriefing(window.mySimulation.state);

            if (period === 1) {
                var a = document.getElementById('analysisInvestInput');
                if (a) decisions.analysisInvest = parseFloat(a.value);
                var f = document.getElementById('focusAreaInput');
                if (f) decisions.focusArea = parseInt(f.value);
                if (!decisions.analysisInvest || decisions.analysisInvest < 10 || decisions.analysisInvest > 80) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('warn_analysis'), 'warning');
                    return false;
                }
            } else if (period === 2) {
                var s = document.getElementById('salaryBudgetInput');
                if (s) decisions.salaryBudget = parseFloat(s.value);
                var b = document.getElementById('bonusPoolInput');
                if (b) decisions.bonusPool = parseFloat(b.value);
                var c = document.getElementById('calibrationInvestInput');
                if (c) decisions.calibrationInvest = parseFloat(c.value);
                if (!decisions.salaryBudget || decisions.salaryBudget < 100 || decisions.salaryBudget > 800) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('warn_salary'), 'warning');
                    return false;
                }
                if (!decisions.bonusPool || decisions.bonusPool < 50 || decisions.bonusPool > 400) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('warn_bonus'), 'warning');
                    return false;
                }
                if (!decisions.calibrationInvest || decisions.calibrationInvest < 10 || decisions.calibrationInvest > 100) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('warn_calibration'), 'warning');
                    return false;
                }
            } else if (period === 3) {
                var r = document.getElementById('recoveryBudgetInput');
                if (r) decisions.recoveryBudget = parseFloat(r.value);
                var t = document.getElementById('trainingBudgetInput');
                if (t) decisions.trainingBudget = parseFloat(t.value);
                if (decisions.recoveryBudget === undefined || decisions.recoveryBudget < 0 || decisions.recoveryBudget > 500) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('warn_recovery'), 'warning');
                    return false;
                }
                if (!decisions.trainingBudget || decisions.trainingBudget < 20 || decisions.trainingBudget > 200) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('warn_training'), 'warning');
                    return false;
                }
            } else if (period === 4) {
                var sp = document.getElementById('implSpeedInput');
                if (sp) decisions.implSpeed = parseInt(sp.value);
                var m = document.getElementById('monitoringInvestInput');
                if (m) decisions.monitoringInvest = parseFloat(m.value);
                if (!decisions.monitoringInvest || decisions.monitoringInvest < 10 || decisions.monitoringInvest > 100) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('warn_monitoring'), 'warning');
                    return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var period = state.currentPeriod;
            var roundCost = 0;
            var retentionDelta = 0;
            var fairnessDelta = 0;
            var satisfactionDelta = 0;
            var talentDelta = 0;
            var narrative = '';

            if (period === 1) {
                roundCost = d.analysisInvest;
                var qualityBase = (d.analysisInvest - 10) / 70;
                var focusMultiplier = d.focusArea === 3 ? 1.0 : 0.55;
                ds.diagnosisQuality = Math.round(qualityBase * focusMultiplier * 100);
                fairnessDelta = Math.round(ds.diagnosisQuality * 0.08);
                satisfactionDelta = Math.round(ds.diagnosisQuality * 0.04);
                retentionDelta = Math.round(ds.diagnosisQuality * 0.02);

                if (ds.diagnosisQuality >= 70) {
                    narrative = window.mySimulation.t('r1_excellent');
                } else if (ds.diagnosisQuality >= 40) {
                    narrative = window.mySimulation.t('r1_moderate');
                } else {
                    narrative = window.mySimulation.t('r1_weak');
                }
            } else if (period === 2) {
                roundCost = d.salaryBudget + d.bonusPool + d.calibrationInvest;
                var salaryScore = Math.min((d.salaryBudget - 100) / 500, 1.0);
                var bonusScore = Math.min((d.bonusPool - 50) / 250, 1.0);
                var calibScore = Math.min((d.calibrationInvest - 10) / 60, 1.0);
                var diagBonus = ds.diagnosisQuality >= 60 ? 1.15 : (ds.diagnosisQuality >= 30 ? 1.0 : 0.8);
                ds.systemDesignScore = Math.round((salaryScore * 35 + bonusScore * 30 + calibScore * 35) * diagBonus);
                ds.systemDesignScore = Math.min(ds.systemDesignScore, 100);
                retentionDelta = Math.round(ds.systemDesignScore * 0.06);
                fairnessDelta = Math.round(calibScore * 25 + bonusScore * 10);
                satisfactionDelta = Math.round(salaryScore * 12 + bonusScore * 10 + calibScore * 5);

                if (ds.systemDesignScore >= 70) {
                    narrative = window.mySimulation.t('r2_excellent');
                } else if (ds.systemDesignScore >= 40) {
                    narrative = window.mySimulation.t('r2_moderate');
                } else {
                    narrative = window.mySimulation.t('r2_weak');
                }
            } else if (period === 3) {
                roundCost = d.recoveryBudget + d.trainingBudget;
                var recoveryProb = Math.min(d.recoveryBudget / 200, 1.0);
                var designBonus = ds.systemDesignScore >= 60 ? 0.2 : 0;
                var effectiveProb = Math.min(recoveryProb + designBonus, 1.0);
                if (effectiveProb >= 0.9) {
                    talentDelta = 3;
                } else if (effectiveProb >= 0.65) {
                    talentDelta = 2;
                } else if (effectiveProb >= 0.35) {
                    talentDelta = 1;
                } else {
                    talentDelta = 0;
                }
                var trainingScore = Math.min((d.trainingBudget - 20) / 130, 1.0);
                ds.communicationScore = Math.round((effectiveProb * 40 + trainingScore * 60));
                retentionDelta = Math.round(talentDelta * 1.5 + trainingScore * 3);
                fairnessDelta = Math.round(trainingScore * 12);
                satisfactionDelta = Math.round(talentDelta * 3 + trainingScore * 10);

                if (talentDelta >= 2 && trainingScore >= 0.5) {
                    narrative = window.mySimulation.t('r3_excellent');
                } else if (talentDelta >= 1) {
                    narrative = window.mySimulation.t('r3_moderate');
                } else {
                    narrative = window.mySimulation.t('r3_weak');
                }
            } else if (period === 4) {
                roundCost = d.monitoringInvest;
                var speedRisk = d.implSpeed === 1 ? 0.7 : (d.implSpeed === 2 ? 1.0 : 0.85);
                var monitorScore = Math.min((d.monitoringInvest - 10) / 60, 1.0);
                var implScore = Math.round((speedRisk * 50 + monitorScore * 50) * (ds.communicationScore >= 50 ? 1.1 : 0.9));
                implScore = Math.min(implScore, 100);
                retentionDelta = Math.round(implScore * 0.04);
                fairnessDelta = Math.round(monitorScore * 8);
                satisfactionDelta = Math.round(implScore * 0.06);

                if (implScore >= 70) {
                    narrative = window.mySimulation.t('r4_excellent');
                } else if (implScore >= 40) {
                    narrative = window.mySimulation.t('r4_moderate');
                } else {
                    narrative = window.mySimulation.t('r4_weak');
                }
            }

            ds.budget -= roundCost;
            ds.retentionRate = Math.min(99, ds.retentionRate + retentionDelta);
            ds.fairnessScore = Math.min(100, ds.fairnessScore + fairnessDelta);
            ds.satisfactionScore = Math.min(100, ds.satisfactionScore + satisfactionDelta);
            ds.talentRecovered += talentDelta;
            ds.talentRecovered = Math.min(ds.talentRecovered, 5);

            ds.budgetHistory.push(ds.budget);
            ds.retentionHistory.push(ds.retentionRate);
            ds.fairnessHistory.push(ds.fairnessScore);
            ds.satisfactionHistory.push(ds.satisfactionScore);

        // --- Persist an overall 0-100 score for the grading/reporting layer ---
        // The DB grade + reports resolve domainState.performance.overallScore, then domainState.score.
        // Same composite formula as getPerformanceSummary (no scoring change) so per-round history,
        // final domainState, and the summary modal all agree.
        var overallScore = Math.round((ds.retentionRate * 0.25) + (ds.fairnessScore * 0.30) + (ds.satisfactionScore * 0.25) + (ds.talentRecovered * 4));
        overallScore = Math.max(0, Math.min(100, overallScore));
        var perfGrade = 'Needs Improvement';
        if (overallScore >= 75) perfGrade = 'Excellent';
        else if (overallScore >= 55) perfGrade = 'Good';
        else if (overallScore >= 40) perfGrade = 'Adequate';
        ds.score = overallScore;
        ds.performance = { overallScore: overallScore, grade: perfGrade };

            var panel = document.getElementById('roundResultsPanel');
            if (panel) panel.style.display = 'block';
            var textEl = document.getElementById('roundResultsText');
            if (textEl) textEl.innerHTML = narrative;

            var self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: period,
                overallScore: overallScore,
                score: overallScore,
                roundCost: roundCost,
                retentionRate: ds.retentionRate,
                fairnessScore: ds.fairnessScore,
                satisfactionScore: ds.satisfactionScore,
                talentRecovered: ds.talentRecovered,
                budgetRemaining: ds.budget
            };
        }

        setupUI(uiManager) {
