                lang = (m && (m.language || m.currentLanguage)) ||
                       (document.documentElement && document.documentElement.getAttribute && document.documentElement.getAttribute('lang')) ||
                       'en';
            } catch (e) { lang = 'en'; }
            return String(lang || 'en').slice(0, 2).toLowerCase() === 'es' ? 'es' : 'en';
        }

        _updateBriefing(state) {
            var period = state.currentPeriod || 1;
            var idx = Math.min(period - 1, 3);
            var lang = this._lang();
            var rounds = lang === 'es' ? this.ROUNDS_ES : this.ROUNDS_EN;
            var round = rounds[idx];

            var briefEl = document.getElementById('briefingText');
            if (briefEl) briefEl.innerHTML = '<strong>' + round.title + '</strong><br><br>' + round.body;

            var ids = ['round1Inputs', 'round2Inputs', 'round3Inputs', 'round4Inputs'];
            for (var i = 0; i < ids.length; i++) {
                var el = document.getElementById(ids[i]);
                if (el) el.style.display = (i === idx && period <= 4) ? 'block' : 'none';
            }

            var resultsPanel = document.getElementById('roundResultsPanel');
            if (resultsPanel && (state.currentPeriod || 1) <= 1) {
                resultsPanel.style.display = 'none';
            }
        }
